function n(id){var v=parseFloat(document.getElementById(id).value);return isNaN(v)?0:v;}
function fmt(x){
  if(!isFinite(x))return '0';
  return Math.round(x).toLocaleString('en-US');
}
function calc(){
  var P=n('p'), annual=n('r'), t=n('t');
  var months=document.getElementById('unit').value==='y'?Math.round(t*12):Math.round(t);
  var note=document.getElementById('note');
  if(P<=0||months<=0){
    ['emi','ti','tp'].forEach(function(id){document.getElementById(id).textContent='0';});
    note.textContent='Enter a loan amount and a term greater than zero.';
    return;
  }
  var i=annual/12/100, emi;
  if(i===0){ emi=P/months; }
  else{
    var f=Math.pow(1+i,months);
    emi=P*i*f/(f-1);
  }
  var total=emi*months, interest=total-P;
  document.getElementById('emi').textContent=fmt(emi);
  document.getElementById('ti').textContent=fmt(interest);
  document.getElementById('tp').textContent=fmt(total);
  var pP=total>0?P/total*100:0;
  document.getElementById('fillP').style.width=pP+'%';
  document.getElementById('fillI').style.width=(100-pP)+'%';
  document.getElementById('pctP').textContent=Math.round(pP)+'%';
  document.getElementById('pctI').textContent=Math.round(100-pP)+'%';
  note.textContent='Over '+months+' months you would pay '+fmt(emi)+' each month, and '+fmt(interest)+' of that total is interest.';
  WT.resize();
}
['p','r','t'].forEach(function(id){document.getElementById(id).addEventListener('input',calc);});
document.getElementById('unit').addEventListener('change',calc);
document.getElementById('go').addEventListener('click',calc);
document.getElementById('copy').addEventListener('click',function(){
  var ok=WT.copy(document.getElementById('emi').textContent);
  document.getElementById('note').textContent=ok?'Monthly instalment copied to clipboard.':'Copy failed, select the number instead.';
});
calc();
